// TH15 v1.00b Stage 3 BossCard1 (th15_s3_b2)
// Source: st03bs.ecl.txt:673-759 entry; 761-859 BossCard1_at; 861-963 BossCard1_at2.
// Card frame 0 = source timerReset (source entry cleanup of 4 frames is outside the
// source limit and is absorbed by the +4 startup margin of TIME_LIMIT).
// Source first wave at t=120; source timeout at t=2220 to "Boss2". The task sheet asks
// for a separate outer budget TIME_LIMIT=2344 (120 opening + 2220 window + 4 margin).

const TH15_RICE: int = 480;      // source etSprite type 8
const TH15_STAR_R: int = 608;    // source etSprite type 16
const RICE_COLOR: int = 5;       // source color 5
const STAR_COLOR: int = 3;       // source color 3
const SPELL_ID: int = 26;
const TIME_LIMIT: int = 2344;
const OPENING_BUFFER: int = 120;

// Source EX chain (BossCard1_at / at2, lines 788-791 / 888-891):
//   ANIM(2,a=1) -> OFFSCREEN(256,a=180,b=0) -> WAIT(0x80000000,a=120)
//   -> VELTIME(0x200000,a=60,r=2.0,s=-999999 preserve angle)
// Approved birth-animation omission: ANIM and its waits are skipped; its
// position -= 4*velocity entry displacement is kept by sh_dist(-1.2fx) with
// birth speed 0.3. OFFSCREEN 180 has two effect completions here (WAIT, VELTIME),
// so it maps to offscreen_keep(178) per the shared OFFSCREEN b=0 rule.
xformdef DREAM_GROW {
    offscreen_keep(178);
    wait(120);
    step_speed(2fx, 60);
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 2000, 0, 0, 0, boss_main);
    loop { wait(1); }
}

// Real boss carries the phase: source entry position (0,128), Boss() hitbox 48x48,
// hurtbox 40x40; card entry moveLimit(0,128,240,64) is enforced by card_arm_next_step.
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);    // setHitbox(48,48) circle branch: 48*0.5
    set_hurtbox(20fx);   // setHurtbox(40,40) circle branch: 40*0.5
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    spell_begin(0, SPELL_ID, card_pattern, TIME_LIMIT, 500000, 0, 0);
    wait_spell();
    loop { wait(1); }
}

// BossCard1 main loop, source lines 721-757. Source state: $A=120, $D=1000 and
// moveRand(60,4,1.0); D=1000 is far beyond the 2220-frame card window, so the
// pattern loops until the phase kills it. Rank branches follow the source masks:
// spawn at() all ranks; at2 twice only on H/L (!HL); L adds an extra wait(10)
// after each wait(70); E/N have no inter-wave wait.
async sub card_pattern() {
    var rank: int = global(GVAR_RANK);
    set_self_int(0, 60);   // park movement helper until the first moveRand
    card_wait(OPENING_BUFFER);
    var a_wait: int = 120; // source $A
    loop {
        // Source 0730-0731: at2 uses the player position read at loop start,
        // while at() reads its own start-of-task position one frame later.
        var px: fx = $player_x;
        var py: fx = $player_y;
        spawn wave_aimed();
        if rank >= RANK_HARD {
            card_wait(70);
            if rank == RANK_LUNATIC { card_wait(10); }
            spawn wave_rand(px, py);
            card_wait(70);
            if rank == RANK_LUNATIC { card_wait(10); }
            spawn wave_rand(px, py);
        }
        card_wait(a_wait);
        if a_wait > 60 { a_wait = a_wait - 5; }
        card_move_rand();
        card_wait(80);
    }
}

// BossCard1_at: source lines 761-859. Both emitters spawn around the player position
// captured at this task's start (`etOffsetAbs`, line 793/814), using the boss-to-player
// angle read here (`ANGLE_PLAYER`, line 815).
async sub wave_aimed() {
    var rank: int = global(GVAR_RANK);
    var px: fx = $player_x;
    var py: fx = $player_y;
    var ap: angle = atan2($player_y - $self_y, $player_x - $self_x);
    var rice_n: int = 2;
    if rank >= RANK_NORMAL { rice_n = 4; }
    // Emitter setup: source emitter 0 (etAim 5, etSprite(8,5), count 2/4) and
    // emitter 1 (etAim 3, etSprite(16,3), count 2); final speed 0.3 both.
    // Kept inline because sh_xform bound inside a returning sync helper is
    // dropped by sh_fire (contract_viol) instead of persisting in the task.
    sh_reset(0);
    sh_sprite(0, TH15_RICE, RICE_COLOR);
    sh_ring(0, 1);
    sh_count(0, rice_n, 1);
    sh_speed(0, 0.3fx, 0fx);
    sh_dist(0, -1.2fx);          // ANIM entry displacement -4*0.3
    sh_xform(0, DREAM_GROW);
    sh_offset_abs(0, px, py);

    sh_reset(1);
    sh_sprite(1, TH15_STAR_R, STAR_COLOR);
    sh_ring(1, 1);
    sh_count(1, 2, 1);
    sh_speed(1, 0.3fx, 0fx);
    sh_dist(1, -1.2fx);
    sh_xform(1, DREAM_GROW);
    sh_offset_abs(1, px, py);

    var steps: int = 16;                 // diffI($D, 9, 16, 16, 34)
    if rank == RANK_EASY { steps = 9; }
    if rank == RANK_LUNATIC { steps = 34; }
    var stepa: angle = 2048bam;          // 0.19635 rad
    var stepc: fx = 8fx;
    var interval: int = 2;
    if rank == RANK_LUNATIC {
        stepa = 1024bam;                 // 0.098175 rad
        stepc = 5fx;
        interval = 1;
    }
    sweep_arcs(ap - 90deg, ap + 90deg, steps, stepa, stepc, interval,
               (32768 / rice_n) as angle);   // aim mode 5 half-step
}

// BossCard1_at2: source lines 861-963. Spawn position is the loop-start player
// snapshot (arguments), sweep angles use the current ANGLE_PLAYER. RANDF2 draws:
// two 10-degree draws for all ranks, and on Lunatic two more 1-degree draws that
// overwrite C/D (lines 0915-0919); all four draws are kept.
async sub wave_rand(px: fx, py: fx) {
    var rank: int = global(GVAR_RANK);
    var ap: angle = atan2($player_y - $self_y, $player_x - $self_x);
    var rice_n: int = 4;
    sh_reset(0);
    sh_sprite(0, TH15_RICE, RICE_COLOR);
    sh_ring(0, 1);
    sh_count(0, rice_n, 1);
    sh_speed(0, 0.3fx, 0fx);
    sh_dist(0, -1.2fx);
    sh_xform(0, DREAM_GROW);
    sh_offset_abs(0, px, py);

    sh_reset(1);
    sh_sprite(1, TH15_STAR_R, STAR_COLOR);
    sh_ring(1, 1);
    sh_count(1, 2, 1);
    sh_speed(1, 0.3fx, 0fx);
    sh_dist(1, -1.2fx);
    sh_xform(1, DREAM_GROW);
    sh_offset_abs(1, px, py);

    var u1: fx = (rand(65536) - 32768) as fx / 32768;
    var cang: angle = ap + 90deg + (((1820fx * u1) as int) as angle);
    var u2: fx = (rand(65536) - 32768) as fx / 32768;
    var dang: angle = ap - 90deg + (((1820fx * u2) as int) as angle);
    if rank == RANK_LUNATIC {
        var u3: fx = (rand(65536) - 32768) as fx / 32768;
        cang = ap + 90deg + (((182fx * u3) as int) as angle);
        var u4: fx = (rand(65536) - 32768) as fx / 32768;
        dang = ap - 90deg + (((182fx * u4) as int) as angle);
    }
    var steps: int = 16;
    if rank == RANK_LUNATIC { steps = 34; }
    var stepa: angle = 2048bam;
    var stepc: fx = 8fx;
    var interval: int = 2;
    if rank == RANK_LUNATIC {
        stepa = 1024bam;
        stepc = 5fx;
        interval = 1;
    }
    sweep_arcs(dang, cang, steps, stepa, stepc, interval,
               (32768 / rice_n) as angle);
}

// Source at()/at2() sweep loop: two mirrored sides per iteration. The source
// fires the +90 side first in at2 and the -90 side first in at; both sides use
// identical emitters and there is no RNG in emission, so the per-frame set is
// unchanged by our fixed -90/+90 order.
sub sweep_arcs(neg0: angle, pos0: angle, steps: int, stepa: angle, stepc: fx,
               interval: int, half: angle) {
    var neg: angle = neg0;
    var pos: angle = pos0;
    var c: fx = 128fx;
    for i in 0..steps {
        sh_offset_rad(0, neg, c);
        sh_offset_rad(1, neg, c);
        sh_angle(0, neg + half, 0deg);
        sh_angle(1, neg, 0deg);
        sh_fire(0);
        sh_fire(1);
        neg = neg - stepa;

        sh_offset_rad(0, pos, c);
        sh_offset_rad(1, pos, c);
        sh_angle(0, pos + half, 0deg);
        sh_angle(1, pos, 0deg);
        sh_fire(0);
        sh_fire(1);
        pos = pos + stepa;

        c = c + stepc;
        wait(interval);
    }
}

// moveRand(60,4,1.0) recipe from TH16/TH18 shared movement notes, with this
// card's entry moveLimit(0,128,240,64): actual x in [-120,120], y in [96,160];
// direction-selection inner region x +-60, y 112..144. Speed is linear
// 1-k/60 and the angle is fixed per call; the direction is sampled once.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}
